  cancel(id: number): Order {
    const order = this.get(id);
    if (order.status !== "PENDING") throw conflict("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
    this.orders.updateStatus(id, "CANCELLED");
    return this.get(id);
  }

  applyCoupon(id: number, couponCode: unknown): Order {
    const order = this.get(id);
    if (typeof couponCode !== "string" || couponCode.trim() === "") {
      throw badRequest("INVALID_REQUEST", "couponCode is required");
    }
    const code = couponCode.trim();
    const coupon = this.coupons.findByCode(code);
    if (!coupon) throw badRequest("COUPON_NOT_FOUND", `coupon ${code} not found`);
    if (coupon.status !== "ACTIVE") throw badRequest("COUPON_NOT_ACTIVE", `coupon ${code} is ${coupon.status}`);

    const now = this.clock().getTime();
    if (now < Date.parse(coupon.validFrom)) {
      throw badRequest("COUPON_NOT_YET_VALID", `coupon ${code} is not valid yet`);
    }
    if (now > Date.parse(coupon.validUntil)) {
      throw badRequest("COUPON_EXPIRED", `coupon ${code} has expired`);
    }
    if (coupon.usageLimit !== null && coupon.usedCount >= coupon.usageLimit) {
      throw badRequest("COUPON_USAGE_LIMIT_REACHED", `coupon ${code} usage limit reached`);
    }
    if (order.status !== "PENDING") {
      throw badRequest("ORDER_NOT_PENDING", `order ${id} is ${order.status}`);
    }
    if (order.amountCents < coupon.minAmountCents) {
      throw badRequest("ORDER_BELOW_MIN_AMOUNT", `order ${id} is below coupon minimum`);
    }

    const rawDiscount =
      coupon.type === "FIXED" ? coupon.value : Math.round((order.amountCents * coupon.value) / 100);
    const capped = coupon.maxDiscountCents === null ? rawDiscount : Math.min(rawDiscount, coupon.maxDiscountCents);
    const discountCents = Math.max(0, Math.min(capped, order.amountCents));
    const finalAmountCents = order.amountCents - discountCents;

    return this.orders.transaction(() => {
      const updated = this.orders.applyCoupon(id, code, discountCents, finalAmountCents);
      this.coupons.recordRedemption(id, code, discountCents, this.clock().toISOString());
      return updated;
    });
  }
}

